prompt:
You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

\section{Input Distribution and its Characteristics}\label{sec:input-distribution}

Let $N$ be a parameter that controls the number of vertices in our input distribution. Moreover, in our construction, let $d \leq n^{\epsilon/3}$ be a parameter that controls the degree of vertices. Graphs in our input distribution have $n = (1/2 + 1/\epsilon + \epsilon - \epsilon^2 / 2)N$ vertices. We first describe the vertex set of the graphs in our distribution.

\paragraph{The vertex set:} The vertex set consists of disjoint subsets $A^1_i, B^1_i, A^2_i, B^2_i$ for each $i \in [1/\epsilon]$  as well as two subsets $S^1$ and $S^2$. Each of these subsets except $A^1_{1/\epsilon}, A^2_{1/\epsilon}, S^1$, and $S^2$, has exactly $N/4$ vertices. Each of $A^1_{1/\epsilon}$ and $A^2_{1/\epsilon}$ has $(1-\epsilon^2 )N/4$ vertices. Also, each of $S^1$ and $S^2$ has $N/4$ vertices. Moreover, the vertex set consists of subsets $D_i$ of {\em delusive vertices} for $i \in [1/\epsilon]$, where each of these $1/\epsilon$ subsets has exactly $\epsilon^2 N$ vertices. So we have
\begin{align*}
    |A^1_i| = |A^2_i| = |B^1_i| = |B^2_i| = \frac{N}{4} \qquad \forall i \in [\frac{1}{\epsilon} - 1],
\end{align*}
\vspace{-0.5cm}
\begin{align*}
    |B^1_{1/\epsilon}| = |B^2_{1/\epsilon}| = \frac{N}{4}, \quad |A^1_{1/ \epsilon}| = |A^2_{1/ \epsilon}| = (1-\epsilon^2)\frac{N}{4},
\end{align*}
\vspace{-0.5cm}
\begin{align*}
    |S^1| = |S^2| = \frac{N}{4},
\end{align*}
\vspace{-0.5cm}
\begin{align*}
    |D_i| = \epsilon^2 N \quad \forall i \in [\frac{1}{\epsilon}].
\end{align*}
Hence, the total number of vertices in each graph of our input distribution is $n = (1/2 + 1/\epsilon + \epsilon - \epsilon^2 / 2)N$. 

\paragraph{The edge set:} For the edge set, we have two different distributions; \yesdist{} and \nodist{}. In \yesdist{}, the graph has an almost perfect matching. On the flip side, a maximum matching of \nodist{} leaves at least $\epsilon n$ vertices unmatched. In our input distribution, we draw the graph from \yesdist{} with probability $1/2$ and from \nodist{} with probability $1/2$.

Let $X, Y \in \bigcup_{i=1}^{1/\epsilon} \{A^1_i, A^2_i, B^1_i,B^2_i, D_i \} \cup \{S^1, S^2\}$ be any two vertex subsets. We use $\deg_X^Y(v)$ to denote the number of vertices of subset $Y$ that are adjacent to a single vertex $v \in X$. First, we show how the degree of vertices will be determined in \yesdist{} and \nodist{}, then we describe how to construct a graph with the corresponding degree sequence. Each vertex except vertices of $S$ has exactly $d' = d + \epsilon^3 d + \log^4 N$ neighbors. Also, all vertices of $S$ have $\log^4 N$ neighbors. For a vertex $u \in X$, the type of its neighbor $v \in Y$ is determined independently at random according to the following binomial distribution for both \yesdist{} and \nodist{} (it helps to recall \cref{fig:delusives} of \cref{sec:techniques}):

\begin{itemize}
    \item Vertices of $S^j$ have $\log^4 N$ neighbors and the neighbors only can be $B^j_1$ for $j \in \{1, 2\}$.
    \item If $X = B^j_1$ for $j \in \{1, 2\}$:
    \begin{align*}
        \Pr[Y = S^j] = \frac{\log^4 N}{d'}, \quad \Pr[Y = A^j_1] = \frac{d}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_1] = \frac{\epsilon^3 d}{d'},
    \end{align*}
    \item If $X = B^j_i$ for $j\in \{1, 2\}$ and $1 < i < 1/\epsilon$:
    \begin{align*}
        \Pr[Y = A^j_{i-1}] = \frac{\log^4 N}{d'}, \quad &\Pr[Y = A^j_i] = \frac{d}{d'},
    \end{align*}
        \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_i] = \frac{(1/\epsilon - i + 1) \epsilon^4 d}{d'},
    \end{align*}
        \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_k] = \frac{\epsilon^4 d}{d'} \quad \text{for $k < i$}.
    \end{align*}

    \item If $X = A^j_i$ for $j \in \{1, 2\}$ and $1 \leq i < 1/\epsilon$:
    \begin{align*}
        \Pr[Y = B^j_{i+1}] = \frac{\log^4 N}{d'}, \quad &\Pr[Y = B^j_i] = \frac{d}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_i] = \frac{(1/\epsilon - i + 1) \epsilon^4 d}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_k] = \frac{\epsilon^4 d}{d'} \quad \text{for $k < i$}.
    \end{align*}
    \item If $X = D_i$ for $i \in [1/\epsilon - 1]$:
    \begin{align*}
        &\Pr[Y = D_i] = \frac{(1-2\epsilon + 2i\epsilon^2 - 5\epsilon^2 / 2 + 3\epsilon^4)d + \log^4 N}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_j] = \frac{\epsilon^4 d}{d'} \quad \text{for $j \neq i$},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = A^j_{1/\epsilon}] = \frac{(\epsilon^2 - \epsilon^4)d}{d'}  \quad \text{for $j \neq i$},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = A^j_i] = \Pr[Y = B^j_i] &= \frac{(1/\epsilon - i + 1)\cdot \epsilon^2 d/4}{d'}\\ 
        &\text{for $j \in \{1, 2\}$},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = A^j_k] &= \Pr[Y = B^j_k] = \Pr[Y = B^j_{1/\epsilon}] = \frac{\epsilon^2 d / 4}{d'}\\ &\text{for $j \in \{1, 2\}$ and $i < k < 1/\epsilon$}.
    \end{align*}
    \item If $X = D_i$ for $i = 1/\epsilon$:
    \begin{align*}
        &\Pr[Y = D_i] = \frac{(1 - 5\epsilon^2 / 2 + 3\epsilon^4)d + \log^4 N}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_j] = \frac{\epsilon^4 d}{d'} \quad \text{for $j \neq i$},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = A^j_{1/\epsilon}] = \frac{(\epsilon^2 - \epsilon^4)d}{d'} \quad \text{for $j \in \{1, 2\}$},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = B^j_{1/\epsilon}] = \frac{\epsilon^2 d/4}{d'} \quad \text{for $j \in \{1, 2\}$}.
    \end{align*}
\end{itemize}

Distribution of neighbors of vertices in $A^j_{1/\epsilon}$ and $B^j_{1/\epsilon}$ for $j \in \{1, 2\}$ is different in \yesdist{} and \nodist{}. The following binomial distribution is the distribution of neighbors in \yesdist{}:

\begin{itemize}
        \item If $X = B^j_{1/\epsilon}$ for $j \in \{1, 2\}$:
    \begin{align*}
        \Pr[Y = A^j_{1/\epsilon-1}] = \frac{\log^4 N}{d'}, \quad \Pr[Y = A^j_{1/\epsilon}] = \frac{(1-\epsilon^2)d}{d'},
    \end{align*}
        \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = B^{3 - j}_{1/\epsilon}] = \frac{\epsilon^2 d}{d'},
    \end{align*}
        \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_k] = \frac{\epsilon^4 d}{d'} \quad \text{for $k \leq 1/\epsilon$}.
    \end{align*}
    \item If $X = A^j_{1/\epsilon}$ for $j \in \{1, 2\}$:
    \begin{align*}
        \Pr[Y = A^{3-j}_{1/\epsilon}] = \frac{\log^4 N}{d'}, \quad \Pr[Y = B^j_{1/\epsilon}] = \frac{d}{d'},
    \end{align*}
            \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_k] = \frac{\epsilon^4 d}{d'} \quad \text{for $k \leq 1/\epsilon$}.
    \end{align*}
    \end{itemize}

        The following binomial distribution is the distribution of neighbors in \nodist{}:
    \begin{itemize}
        \item If $X = B^j_{1/\epsilon}$ for $j \in \{1, 2\}$:
    \begin{align*}
        &\Pr[Y = A^j_{1/\epsilon-1}] = \frac{\log^4 N}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = A^j_{1/\epsilon}] = \frac{(1-\epsilon^2)(d+\log^4 N)}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = B^{3 - j}_{1/\epsilon}] = \frac{\epsilon^2 (d+\log^4 N) - \log^4 N}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_k] = \frac{\epsilon^4 d}{d'} \quad \text{for $k \leq 1/\epsilon$}.
    \end{align*}
    \item If $X = A^j_{1/\epsilon}$ for $j \in \{1, 2\}$:
    \begin{align*}
       \Pr[Y = B^j_{1/\epsilon}] = \frac{d+ \log^4 N}{d'},
    \end{align*}
    \vspace{-0.5cm}
    \begin{align*}
        \Pr[Y = D_k] = \frac{\epsilon^4 d}{d'} \quad \text{for $k \leq 1/\epsilon$}.
    \end{align*}
\end{itemize}

\begin{definition}[Broken Vertices]
    Take a vertex $v$ in our input graph. We say $v$ is a broken vertex if its degree in the final graph is different from the degree initially drawn from the binomial distribution.
\end{definition}

\begin{lemma}\label{lem:convert-degree-to-edge}
Let $a_1 \geq a_2 \geq \ldots \geq a_{k_1}$ and $b_1 \geq b_2 \geq \ldots \geq b_{k_2}$ be two sequences of non-negative integers where $a_i$ is drawn from a Binomial distribution with $\eta_1$ trials and success probability $\rho_1$, and $b_i$ is drawn from a Binomial distribution with $\eta_2$ trials and success probability $\rho_2$ for all $i$, and suppose $\sum_i^{k_1}a_i \geq \sum_i^{k_2}b_i$. Also, assume that $k_1\eta_1 \rho_1 = k_2\eta_2 \rho_2$, $\eta_1 \rho_1 = \Omega(\log^4 n)$, $\eta_2 \rho_2 = \Omega(\log^4 n)$, $\eta_1 \rho_1 = O(d)$, $\eta_2 \rho_2 = O(d)$, $k_1 = \Theta(n)$, and $k_2 = \Theta(n)$. Then, with high probability, there exists a sequence of non-negative integers $a'_1 \geq a'_2 \geq \ldots \geq a'_{k_1}$ such that all the following hold:
\begin{itemize}
    \item $0 \leq a_i - a'_i \leq 10\sqrt{\eta_1 \rho_1} \log n$ for all $i$,
    \item $(a'_1, a'_2, \ldots, a'_{k_1})$ and $(b_1, b_2, \ldots, b_{k_2})$ is a bigraphic pair of sequences (see \cref{def:bigarphic}), and
    \item there are at most $O(\sqrt{k_1 \eta_1 \rho_1}\cdot \log n)$ elements in the sequence where $a_i \neq a_i'$.
\end{itemize}
\end{lemma}

\begin{remark}\label{rem:bipartite-note}
    Note that there are edges inside $D_i$ for each $i \in [1/\epsilon]$, hence, we cannot use \Cref{lem:convert-degree-to-edge} to put edges in $G[D_i]$ since the graph is not bipartite. However, we can assume that the number of vertices in each $D_i$ is even, and there are two parts in each $D_i$ where vertices of each part are only connected to the other part. With this small modification, we can use \Cref{lem:convert-degree-to-edge} for $G[D_i]$.
\end{remark}

\begin{corollary}\label{cor:matching-size-query}
Let $\epsilon < 0.07$. Any algorithm that estimates the size of maximum matching of a graph $G$ that is drawn from input distribution within a factor of $(1, \epsilon n / 7)$ with probability at least 0.51, must be able to distinguish whether $G$ belongs to \yesdist{} or \nodist{}.
\end{corollary}

\begin{lemma}\label{lem:rooted-forest}
    Let $\mathcal{A}$ be any algorithm that makes at most $o(d^{1/\epsilon})$ queries. Let $F_0$ be the empty graph before the algorithm makes any queries, and for $t > 0$, let $F_t$ be the subgraph that $\mathcal{A}$ discovers after $t$ queries. The following property holds throughout the execution of $\mathcal{A}$ with probability $1 - o(1)$: Suppose that the $t$-th query is made to the adjacency list of vertex $u$ and edge $(u, v)$ is returned. Then, vertex $v$ is a singleton vertex in $F_{t-1}$.
\end{lemma}

\paragraph{Labels of vertices:} We use $S$ as the label of vertices in subset $S^1$ and $S^2$, $A_i$ for vertices in subset $A^1_i$ and $A^2_i$, $B_i$ for vertices in subset $B^1_i$ and $B^2_i$, and $D_i$ for vertices in subset $D_i$ for $i \in [1/\epsilon]$.

\paragraph{Transition probabilities:} Suppose that we condition on the high probability event that the algorithm does not query any broken vertex. Let $(u,v)$ be an edge in the forest that is queried by the algorithm and $u$ is the parent of $v$. Then, if $u$ has label $X$ and $v$ has label $Y$ for $X, Y \in \bigcup_{i=1}^{1/\epsilon}\{A_i, B_i, D_i\} \cup \{S\}$, then the transition probabilities from label $X$ to label $Y$ is according to the binomial distribution for neighbors of $X$ in \Cref{sec:input-distribution}.

\begin{definition}[Special Edges]\label{def:special-edge}
    We call an edge $(u,v)$ special, if one of the following holds:
    \begin{itemize}
        \item $u \in B_i$ and $v \in A_{i-1}$, or $u \in A_{i-1}$ and $v \in B_i$ for $1 < i \leq 1/\epsilon$,
        \item $u \in S$ and $v \in B_1$, or $u \in B_1$ and $v \in S$,
        \item Let $p = (1-2\epsilon + 2i\epsilon^2 - 5\epsilon^2 / 2 + 3\epsilon^4)d + \log^4 N$. For each vertex in $D_i$, each of its neighbors to $D_i$ has a probability of $\log^4 N / p$ to be special (in other words, we can assume that there is $\log^4 N$ regular graph of special edges in each $D_i$),
        \item $(u,v)$ is among edges that only exists in exactly one of \yesdist{} or \nodist{}.
    \end{itemize}
\end{definition}

\begin{definition}[Mixer Vertices]\label{def:mixer-vertex}
Let $T$ be a rooted tree and $u$ be its root. Suppose that we are given that $u \in \{A_{1/\epsilon}, B_{1/\epsilon}, D_{1/\epsilon} \}$. Let $v$ be a vertex in $T$ and suppose that there are $k$ special edges on the path between $u$ and $v$. If $k < 1/\epsilon - 1$, we say $v$ is a mixer vertex if and only if $v \in \bigcup_{i=1}^{1/\epsilon-k-1} D_j$.
\end{definition}

\begin{corollary}\label{cor:mixer-vertex-in-tree}    Let $\mathcal{A}$ be any algorithm that makes at most $o(d^{1/\epsilon - 1})$ queries and $T$ be one of the rooted trees queried by the algorithm. Moreover, assume that the root of the tree is a vertex with level $1/\epsilon$. Then, with probability at least $1 - \widetilde{O}(|V(T)|/d^{1/\epsilon - 1})$, all paths between root and $S$ vertices in the tree contain a mixer vertex.
\end{corollary}

Let $E_{Y} = \{(u,v) \lvert (u,v) \in E, u \in A^1_{1/\epsilon}, v \in A^2_{1/\epsilon} \}$, and $E_Y^Q$ be the subset of $E_Y$ that the algorithm discovers. Moreover, let $V_Y^Q = \{ v \mid (u, v) \in E_Y\}$ where $u$ is the parent of $v$ in the queried rooted forest by algorithm $\mathcal{A}$. Also, assume that we remove all vertices of $V_Y^Q$ that have at least one ancestor in the forest which is in $V_Y^Q$.

\begin{claim}\label{clm:no-bad-event}
    Let $F$ be a forest that is queried by an algorithm $\mathcal{A}$ using at most $Q = o(d^{1/(2\epsilon)})$ queries. Then, with probability at least $1 - \widetilde{O}(Q^2/d^{1/\epsilon})$, all paths between the vertices of $V_Y^Q$ and a vertex in its subtree that have more than $1/\epsilon - 2$ special edges, contain a mixer vertex. 
\end{claim}

We define a {\em bad event} to be the event that $\mathcal{A}$ finds a path between a vertex in $V_Y^Q$ and a vertex in its subtree that has more than $1/\epsilon - 2$ special edges without any mixer vertex.


********** END CONTEXT **********

